{"database": "bible_research", "name": "wa_quality_flag_types_cascade_delete", "table_name": "wa_quality_flag_types", "ordinal": 1, "sql": "CREATE TRIGGER wa_quality_flag_types_cascade_delete
AFTER UPDATE OF delete_flagged ON wa_quality_flag_types
WHEN NEW.delete_flagged = 1 AND OLD.delete_flagged = 0
BEGIN
    UPDATE wa_data_quality_flags SET delete_flagged = 1 WHERE flag_id = NEW.id;
END", "inactive": 0, "use": "removes a quality flag type's flags with it"}

{"database": "bible_research", "name": "prose_section_au", "table_name": "prose_section", "ordinal": 4, "sql": "CREATE TRIGGER prose_section_au AFTER UPDATE ON prose_section BEGIN
        DELETE FROM prose_section_fts WHERE rowid = old.id;
        INSERT INTO prose_section_fts(rowid, body, heading, section_type_code,
                                      registry_id, cluster_code, characteristic_id, status)
        VALUES (new.id, new.body, new.heading,
                (SELECT code FROM "prose_section_type" WHERE id=new.section_type_id),
                new.registry_id, new.cluster_code, new.characteristic_id, new.status);
    END", "inactive": 0, "use": "keeps prose_section_fts in step on update"}

{"database": "iba", "name": "trg_narrative_claim_ref_ai", "table_name": "narrative_claim", "ordinal": 0, "sql": "CREATE TRIGGER trg_narrative_claim_ref_ai AFTER INSERT ON narrative_claim WHEN NEW.claim_ref IS NULL
BEGIN
  UPDATE narrative_claim SET claim_ref = 'C-' || NEW.id WHERE id = NEW.id;
END", "use": "a new claim with no claim_ref is given C-{id} (spec sec3.3) -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_claim_ai", "table_name": "narrative_claim", "ordinal": 1, "sql": "CREATE TRIGGER trg_narrative_claim_ai AFTER INSERT ON narrative_claim
BEGIN
  INSERT INTO narrative_claim_change (claim_id, change_date, change_kind, claim_after, verdict_after, chapter_id, section_id, basis, provenance, created_by)
  VALUES (NEW.id, substr(NEW.created_at, 1, 10), 'claim created', NEW.claim_text, NEW.verdict, NEW.main_chapter_id, NEW.main_section_id, 'direct edit', 'trigger trg_narrative_claim_ai', 'trigger');
END", "use": "every new claim writes its 'claim created' change row -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_claim_text_au", "table_name": "narrative_claim", "ordinal": 2, "sql": "CREATE TRIGGER trg_narrative_claim_text_au AFTER UPDATE OF claim_text ON narrative_claim WHEN OLD.claim_text IS NOT NEW.claim_text
BEGIN
  INSERT INTO narrative_claim_change (claim_id, change_date, change_kind, claim_before, claim_after, basis, provenance, created_by)
  VALUES (NEW.id, date('now'), 'edited', OLD.claim_text, NEW.claim_text, 'direct edit', 'trigger trg_narrative_claim_text_au', 'trigger');
END", "use": "a change to a claim's wording writes its before and after (test plan 2.4) -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_claim_verdict_au", "table_name": "narrative_claim", "ordinal": 3, "sql": "CREATE TRIGGER trg_narrative_claim_verdict_au AFTER UPDATE OF verdict ON narrative_claim WHEN OLD.verdict IS NOT NEW.verdict
BEGIN
  INSERT INTO narrative_claim_change (claim_id, change_date, change_kind, verdict_before, verdict_after, basis, provenance, created_by)
  VALUES (NEW.id, date('now'), 'verdict changed', OLD.verdict, NEW.verdict, 'direct edit', 'trigger trg_narrative_claim_verdict_au', 'trigger');
END", "use": "a change of verdict writes its before and after (test plan 2.5) -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_claim_status_au", "table_name": "narrative_claim", "ordinal": 4, "sql": "CREATE TRIGGER trg_narrative_claim_status_au AFTER UPDATE OF status ON narrative_claim WHEN OLD.status IS NOT NEW.status
BEGIN
  INSERT INTO narrative_claim_change (claim_id, change_date, change_kind, claim_before, claim_after, note, basis, provenance, created_by)
  VALUES (NEW.id, date('now'), CASE NEW.status WHEN 'withdrawn' THEN 'claim withdrawn' ELSE 'edited' END, NEW.claim_text, NEW.claim_text, 'status: ' || OLD.status || ' -> ' || NEW.status, 'direct edit', 'trigger trg_narrative_claim_status_au', 'trigger');
END", "use": "a change of status (withdrawn, held, current) is logged -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_passage_text_au", "table_name": "narrative_passage", "ordinal": 0, "sql": "CREATE TRIGGER trg_narrative_passage_text_au AFTER UPDATE OF passage_text ON narrative_passage WHEN OLD.passage_text IS NOT NEW.passage_text
BEGIN
  INSERT INTO narrative_claim_change (claim_id, passage_id, change_date, change_kind, passage_before, passage_after, chapter_id, section_id, basis, provenance, created_by)
  SELECT t.claim_id, NEW.id, date('now'), 'telling changed', OLD.passage_text, NEW.passage_text, NEW.chapter_id, NEW.section_id, 'direct edit', 'trigger trg_narrative_passage_text_au', 'trigger' FROM narrative_claim_telling t WHERE t.passage_id = NEW.id AND t.status = 'current';
END", "use": "a change to a passage writes one row per claim it tells, with the passage before and after (test plan 2.6) -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_passage_move_au", "table_name": "narrative_passage", "ordinal": 1, "sql": "CREATE TRIGGER trg_narrative_passage_move_au AFTER UPDATE OF chapter_id, section_id ON narrative_passage WHEN OLD.chapter_id IS NOT NEW.chapter_id OR OLD.section_id IS NOT NEW.section_id
BEGIN
  INSERT INTO narrative_claim_change (claim_id, passage_id, change_date, change_kind, passage_after, chapter_id, section_id, section_before_id, note, basis, provenance, created_by)
  SELECT t.claim_id, NEW.id, date('now'), 'passage moved', NEW.passage_text, NEW.chapter_id, NEW.section_id, OLD.section_id, 'moved from chapter id ' || OLD.chapter_id, 'direct edit', 'trigger trg_narrative_passage_move_au', 'trigger' FROM narrative_claim_telling t WHERE t.passage_id = NEW.id AND t.status = 'current';
END", "use": "a passage moved to another chapter or section keeps its row and its claims; the move is logged with where from (spec sec3.1) -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_passage_retire_au", "table_name": "narrative_passage", "ordinal": 2, "sql": "CREATE TRIGGER trg_narrative_passage_retire_au AFTER UPDATE OF last_version ON narrative_passage WHEN (OLD.last_version IS NULL) <> (NEW.last_version IS NULL)
BEGIN
  UPDATE narrative_claim SET in_narrative = (SELECT EXISTS (SELECT 1 FROM narrative_claim_telling t JOIN narrative_passage p ON p.id = t.passage_id WHERE t.claim_id = narrative_claim.id AND t.status = 'current' AND t.kind <> 'pointer' AND p.last_version IS NULL)) WHERE id IN (SELECT claim_id FROM narrative_claim_telling WHERE passage_id = NEW.id);
END", "use": "a passage that leaves (or returns to) the current narrative updates in_narrative of the claims it tells (test plan 2.9) -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_telling_ai", "table_name": "narrative_claim_telling", "ordinal": 0, "sql": "CREATE TRIGGER trg_narrative_telling_ai AFTER INSERT ON narrative_claim_telling
BEGIN
  INSERT INTO narrative_claim_change (claim_id, passage_id, change_date, change_kind, passage_after, chapter_id, section_id, note, basis, provenance, created_by)
  SELECT NEW.claim_id, NEW.passage_id, substr(NEW.created_at, 1, 10), 'telling added', p.passage_text, p.chapter_id, p.section_id, NEW.kind || COALESCE(': ' || NEW.part_told, ''), 'direct edit', 'trigger trg_narrative_telling_ai', 'trigger' FROM narrative_passage p WHERE p.id = NEW.passage_id;
  UPDATE narrative_claim SET in_narrative = (SELECT EXISTS (SELECT 1 FROM narrative_claim_telling t JOIN narrative_passage p ON p.id = t.passage_id WHERE t.claim_id = narrative_claim.id AND t.status = 'current' AND t.kind <> 'pointer' AND p.last_version IS NULL)) WHERE id = NEW.claim_id;
END", "use": "a new telling writes 'telling added' and updates in_narrative (test plan 2.7, 2.9) -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_telling_status_au", "table_name": "narrative_claim_telling", "ordinal": 1, "sql": "CREATE TRIGGER trg_narrative_telling_status_au AFTER UPDATE OF status ON narrative_claim_telling WHEN OLD.status IS NOT NEW.status
BEGIN
  INSERT INTO narrative_claim_change (claim_id, passage_id, change_date, change_kind, passage_before, passage_after, chapter_id, section_id, note, basis, provenance, created_by)
  SELECT NEW.claim_id, NEW.passage_id, date('now'), CASE NEW.status WHEN 'removed' THEN 'telling removed' ELSE 'telling added' END, CASE NEW.status WHEN 'removed' THEN p.passage_text END, CASE NEW.status WHEN 'removed' THEN NULL ELSE p.passage_text END, p.chapter_id, p.section_id, 'status: ' || OLD.status || ' -> ' || NEW.status, 'direct edit', 'trigger trg_narrative_telling_status_au', 'trigger' FROM narrative_passage p WHERE p.id = NEW.passage_id;
  UPDATE narrative_claim SET in_narrative = (SELECT EXISTS (SELECT 1 FROM narrative_claim_telling t JOIN narrative_passage p ON p.id = t.passage_id WHERE t.claim_id = narrative_claim.id AND t.status = 'current' AND t.kind <> 'pointer' AND p.last_version IS NULL)) WHERE id = NEW.claim_id;
END", "use": "a telling removed (or restored) is logged and updates in_narrative (test plan 2.7, 2.9) -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_telling_kind_au", "table_name": "narrative_claim_telling", "ordinal": 2, "sql": "CREATE TRIGGER trg_narrative_telling_kind_au AFTER UPDATE OF kind, part_told ON narrative_claim_telling WHEN OLD.kind IS NOT NEW.kind OR OLD.part_told IS NOT NEW.part_told
BEGIN
  INSERT INTO narrative_claim_change (claim_id, passage_id, change_date, change_kind, passage_after, chapter_id, section_id, note, basis, provenance, created_by)
  SELECT NEW.claim_id, NEW.passage_id, date('now'), 'telling changed', p.passage_text, p.chapter_id, p.section_id, 'kind: ' || OLD.kind || ' -> ' || NEW.kind || '; part: ' || COALESCE(OLD.part_told, '-') || ' -> ' || COALESCE(NEW.part_told, '-'), 'direct edit', 'trigger trg_narrative_telling_kind_au', 'trigger' FROM narrative_passage p WHERE p.id = NEW.passage_id;
  UPDATE narrative_claim SET in_narrative = (SELECT EXISTS (SELECT 1 FROM narrative_claim_telling t JOIN narrative_passage p ON p.id = t.passage_id WHERE t.claim_id = narrative_claim.id AND t.status = 'current' AND t.kind <> 'pointer' AND p.last_version IS NULL)) WHERE id = NEW.claim_id;
END", "use": "a change to how a passage tells a claim (kind, part told) is logged -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_telling_ad", "table_name": "narrative_claim_telling", "ordinal": 3, "sql": "CREATE TRIGGER trg_narrative_telling_ad AFTER DELETE ON narrative_claim_telling
BEGIN
  INSERT INTO narrative_claim_change (claim_id, passage_id, change_date, change_kind, passage_before, note, basis, provenance, created_by)
  SELECT OLD.claim_id, OLD.passage_id, date('now'), 'telling removed', (SELECT passage_text FROM narrative_passage WHERE id = OLD.passage_id), 'telling row deleted', 'direct edit', 'trigger trg_narrative_telling_ad', 'trigger';
  UPDATE narrative_claim SET in_narrative = (SELECT EXISTS (SELECT 1 FROM narrative_claim_telling t JOIN narrative_passage p ON p.id = t.passage_id WHERE t.claim_id = narrative_claim.id AND t.status = 'current' AND t.kind <> 'pointer' AND p.last_version IS NULL)) WHERE id = OLD.claim_id;
END", "use": "a deleted telling row (the tool never deletes; Untell sets status removed) is still logged -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_chapter_no_bi", "table_name": "narrative_chapter", "ordinal": 0, "sql": "CREATE TRIGGER trg_narrative_chapter_no_bi BEFORE INSERT ON narrative_chapter WHEN NEW.inactive = 0 AND EXISTS (SELECT 1 FROM narrative_chapter WHERE chapter_no = NEW.chapter_no AND inactive = 0)
BEGIN
  SELECT RAISE(ABORT, 'narrative_chapter: chapter_no is already used by an active chapter');
END", "use": "chapter_no unique among active rows (test plan 2.3) -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_chapter_no_bu", "table_name": "narrative_chapter", "ordinal": 1, "sql": "CREATE TRIGGER trg_narrative_chapter_no_bu BEFORE UPDATE OF chapter_no, inactive ON narrative_chapter WHEN NEW.inactive = 0 AND EXISTS (SELECT 1 FROM narrative_chapter WHERE chapter_no = NEW.chapter_no AND inactive = 0 AND id <> NEW.id)
BEGIN
  SELECT RAISE(ABORT, 'narrative_chapter: chapter_no is already used by an active chapter');
END", "use": "chapter_no unique among active rows (test plan 2.3) -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_chapter_renumber_au", "table_name": "narrative_chapter", "ordinal": 2, "sql": "CREATE TRIGGER trg_narrative_chapter_renumber_au AFTER UPDATE OF chapter_no ON narrative_chapter WHEN OLD.chapter_no IS NOT NEW.chapter_no
BEGIN
  INSERT INTO narrative_claim_change (claim_id, change_date, change_kind, chapter_id, note, basis, provenance, created_by)
  SELECT DISTINCT t.claim_id, date('now'), 'renumbered', NEW.id, 'Ch ' || OLD.chapter_no || ' -> Ch ' || NEW.chapter_no, 'direct edit', 'trigger trg_narrative_chapter_renumber_au', 'trigger' FROM narrative_claim_telling t JOIN narrative_passage p ON p.id = t.passage_id WHERE p.chapter_id = NEW.id AND t.status = 'current';
END", "use": "a renumbered chapter is logged on every claim it tells (spec sec3.1) -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_claim_source_verse_bi", "table_name": "narrative_claim_source", "ordinal": 0, "sql": "CREATE TRIGGER trg_narrative_claim_source_verse_bi BEFORE INSERT ON narrative_claim_source WHEN NEW.verse_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM verse WHERE id = NEW.verse_id)
BEGIN
  SELECT RAISE(ABORT, 'narrative_claim_source: verse_id has no verse row');
END", "use": "a verse_id that names no verse row is refused (test plan 2.2); NULL is allowed -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_claim_source_verse_bu", "table_name": "narrative_claim_source", "ordinal": 1, "sql": "CREATE TRIGGER trg_narrative_claim_source_verse_bu BEFORE UPDATE OF verse_id ON narrative_claim_source WHEN NEW.verse_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM verse WHERE id = NEW.verse_id)
BEGIN
  SELECT RAISE(ABORT, 'narrative_claim_source: verse_id has no verse row');
END", "use": "a verse_id that names no verse row is refused (test plan 2.2); NULL is allowed -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_citation_verse_bi", "table_name": "narrative_citation", "ordinal": 0, "sql": "CREATE TRIGGER trg_narrative_citation_verse_bi BEFORE INSERT ON narrative_citation WHEN NEW.verse_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM verse WHERE id = NEW.verse_id)
BEGIN
  SELECT RAISE(ABORT, 'narrative_citation: verse_id has no verse row');
END", "use": "a verse_id that names no verse row is refused (test plan 2.2); NULL is allowed -- escalation #2110", "inactive": 0}

{"database": "iba", "name": "trg_narrative_citation_verse_bu", "table_name": "narrative_citation", "ordinal": 1, "sql": "CREATE TRIGGER trg_narrative_citation_verse_bu BEFORE UPDATE OF verse_id ON narrative_citation WHEN NEW.verse_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM verse WHERE id = NEW.verse_id)
BEGIN
  SELECT RAISE(ABORT, 'narrative_citation: verse_id has no verse row');
END", "use": "a verse_id that names no verse row is refused (test plan 2.2); NULL is allowed -- escalation #2110", "inactive": 0}

{"sql": "CREATE TRIGGER trg_narrative_passage_move_au AFTER UPDATE OF chapter_id, section_id ON narrative_passage WHEN (OLD.chapter_id IS NOT NEW.chapter_id OR OLD.section_id IS NOT NEW.section_id) AND NOT (OLD.chapter_id IS NEW.chapter_id AND (SELECT renamed_from_id FROM narrative_section WHERE id = NEW.section_id) IS OLD.section_id)
BEGIN
  INSERT INTO narrative_claim_change (claim_id, passage_id, change_date, change_kind, passage_after, chapter_id, section_id, section_before_id, note, basis, provenance, created_by)
  SELECT t.claim_id, NEW.id, date('now'), 'passage moved', NEW.passage_text, NEW.chapter_id, NEW.section_id, OLD.section_id, 'moved from chapter id ' || OLD.chapter_id, 'direct edit', 'trigger trg_narrative_passage_move_au', 'trigger' FROM narrative_claim_telling t WHERE t.passage_id = NEW.id AND t.status = 'current';
END", "use": "a passage moved to another chapter or section keeps its row and its claims; the move is logged with where from (spec sec3.1). A heading renamed in place (the new section row's renamed_from_id is the old one) is not a move -- escalation #2110"}

